def R(a, b): return f'{a} : {b}'
def simp(a, b):
    a, b = Fr(a), Fr(b)
    L = a.denominator * b.denominator // gcd(a.denominator, b.denominator)
    x, y = int(a * L), int(b * L); g = gcd(x, y)
    return x // g, y // g

